SELECT * from customer limit 20;
-- Q1.What is the total rervenue generated by male vs female customers
SELECT gender, SUM(purchase_amount)
FROM customer 
GROUP BY gender;
-- Q2.Which customes used a discount but still spent more than the average purchase amount
SELECT customer_id, purchase_amount
FROM customer
WHERE discount_applied='Yes'
AND purchase_amount>=(SELECT AVG(purchase_amount) from customer);
-- Q3.Which are the top 5 products with highest average review rating?
SELECT item_purchased,
ROUND(AVG(review_rating::numeric),2) as Average_rating
FROM customer
GROUP BY item_purchased
ORDER BY AVG(review_rating) desc
LIMIT 5;
-- The '::' operator does the type casting of the review_rating column to numeric
-- Q4.Compare the average purchase amounts between standard and express shipping
SELECT shipping_type,
ROUND(AVG(purchase_amount),2)
FROM customer
WHERE shipping_type in ('Standard','Express')
GROUP BY shipping_type;
-- Q5.Do subscribed customers spend more? Compare average spend and 
-- total revenue between subscribers and non-subscriber
SELECT subscription_status,
COUNT(customer_id) AS total_customers,
SUM(purchase_amount) AS total_revenue,
ROUND(AVG(purchase_amount),2) AS average_revenue
FROM customer
GROUP BY subscription_status
ORDER BY total_revenue,average_revenue desc;
-- Q5.Which 5 products have the highest percentage of purchases with discounts applied?
SELECT item_purchased,
ROUND(100 * SUM(CASE WHEN discount_applied='Yes' THEN 1 ELSE 0 END)/COUNT(*),2) AS discount_rate
FROM customer
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5;
-- Q6.Segment customers into New, Returning and Loyal based on their total 
-- number of previous purchases, and show the count of each segment.
with customer_type as(
SELECT customer_id, previous_purchases,
CASE 
	WHEN previous_purchases = 1 THEN 'New'
	WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
	ELSE 'Loyal'
	END AS customer_segment
FROM customer
)
SELECT customer_segment, count(*) as "Number Of Customers"
FROM customer_type
GROUP BY customer_segment;
-- Q8.What are the top 3 most purchased products within each category?
with item_counts as (
SELECT category,
item_purchased,
COUNT(customer_id) as total_orders,
ROW_NUMBER() OVER(PARTITION BY category ORDER BY COUNT(customer_id) DESC) as item_rank
FROM customer
GROUP BY category,item_purchased
)
SELECT item_rank, category, item_purchased, total_orders
FROM item_counts
WHERE item_rank<=3;
-- Q9. Are customers who are repeat buyers(more than 5 previous purchases) also likely to subscribe?
SELECT subscription_status,
count(customer_id) as repeat_buyers
from customer
where previous_purchases>5
group by subscription_status;
-- Q10.What is the revenue contribution for each age group
SELECT age_group,
SUM(purchase_amount) as total_revenue
FROM customer
GROUP BY age_group
ORDER BY total_revenue DESC;